INSERT INTO `posts` (`id`, `autor`, `username`, `conteudo`, `vibe`, `parent_id`, `is_deleted`, `is_locked`, `visibility`, `data_criacao`, `data_envio`, `context_label`) VALUES
(1, 'Lottie Matthews', 'lottiematthews', 'so glad to finally be here! can\'t wait to see what happens ✨', 'excited', NULL, 0, 0, 'public', '2026-08-14 17:34:28', '2026-08-14 17:34:28', 'Twitter Web App'),
(2, 'Overheard at Columbia', 'overheardCU', 'Spotted: A certain pre-law sophomore crying in the library because their \'study date\' is actually just a hookup. Embarrassing. 💅', 'toxic', NULL, 0, 0, 'public', '2026-08-14 17:34:33', '2026-08-14 17:34:33', 'Twitter Web App'),
(3, 'Overheard at Columbia', 'overheardCU', 'Spotted: A certain freshman already trying too hard to \'network\' with the upperclassmen. We see you, Lottie. 🙄💅', 'toxic', NULL, 0, 0, 'public', '2026-08-14 17:35:31', '2026-08-14 17:35:31', 'Twitter Web App'),
(4, 'Lottie Matthews', 'lottiematthews', 'who even is this? some people are actually obsessed with me lol 🙄', 'frustrated', NULL, 0, 0, 'public', '2026-08-14 17:36:28', '2026-08-14 17:36:28', 'Twitter Web App'),
(5, 'Overheard at Columbia', 'overheardCU', 'Spotted: Lottie Matthews acting like she\'s the main character in her latest post. Honey, you\'re a freshman, sit down. 🙄💅', 'toxic', NULL, 0, 0, 'public', '2026-08-14 17:36:32', '2026-08-14 17:36:32', 'Twitter Web App'),
(6, 'Lottie Matthews', 'lottiematthews', 'literally who cares about a gossip page lol just ignore the haters 🙄💅', 'frustrated', NULL, 0, 0, 'public', '2026-08-14 17:37:26', '2026-08-14 17:37:26', 'Twitter Web App'),
(7, 'Overheard at Columbia', 'overheardCU', 'Spotted: Lottie Matthews acting like she\'s \'finally here\' when she\'s been posting about it for three months. The desperation is loud. 🙄💅', 'toxic', NULL, 0, 0, 'public', '2026-08-14 17:37:31', '2026-08-14 17:37:31', 'Twitter Web App'),
(8, 'Lottie Matthews', 'lottiematthews', 'the obsession is actually getting scary at this point 💀 stay mad!!', 'frustrated', NULL, 0, 0, 'public', '2026-08-14 17:38:30', '2026-08-14 17:38:30', 'Twitter Web App'),
